  /// Resolve a canonical genre/sub-genre label to a preset bundle key.
  /// Uses exact match first, then falls back to longest substring match,
  /// then to 'default' if nothing matches.
  static String? bundleKeyForGenre(String? genre) {
    if (genre == null || genre.isEmpty) return null;
    final trimmed = genre.trim();
    for (final entry in genrePresetAlias.entries) {
      if (entry.key.toLowerCase() == trimmed.toLowerCase()) {
        return entry.value;
      }
    }
    // Longest-match fallback (sort keys by length desc so specific wins)
    String? best;
    int bestLen = 0;
    final lower = trimmed.toLowerCase();
    for (final entry in genrePresetAlias.entries) {
      if (lower.contains(entry.key.toLowerCase()) && entry.key.length > bestLen) {
        best = entry.value;
        bestLen = entry.key.length;
      }
    }
    return best;
  }

  /// Get the instrument voice rows for a genre label, or empty list if unknown.
  static List<Map<String, String>> voicesForGenre(String? genre) {
    final key = bundleKeyForGenre(genre);
    if (key == null) return const [];
    return byGenre[key] ?? const [];
  }

